WITH cleaned AS (SELECT *, DATEDIFF(CURRENT_DATE(), launch_date) AS days_since_launch_date, price + cost AS margin, COALESCE(brand, 'OTHER') AS resolved_brand FROM products WHERE supplier_id IS NOT NULL), metrics AS (SELECT id, product_name, category, brand, price, cost, stock_qty, launch_date, tags, supplier_id, days_since_launch_date, margin, resolved_brand, NTILE(4) OVER (PARTITION BY supplier_id ORDER BY stock_qty DESC, id) AS stock_qty_bucket, LEAD(days_since_launch_date, 1) OVER (PARTITION BY category ORDER BY margin, id) AS next_days_since_launch_date, FIRST_VALUE(stock_qty) IGNORE NULLS OVER (ORDER BY price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_stock_qty, ROW_NUMBER() OVER w_hist AS row_seq FROM cleaned WINDOW w_hist AS (PARTITION BY brand ORDER BY cost DESC, id)), kept AS (SELECT s.* FROM metrics s WHERE NOT EXISTS (SELECT 1 FROM order_items c WHERE c.product_id = s.id AND c.product_id IS NOT NULL)), ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY category ORDER BY first_known_stock_qty DESC, id) AS rn FROM kept QUALIFY rn = 1) SELECT id, category, brand, stock_qty, launch_date, supplier_id, days_since_launch_date, margin, resolved_brand, CASE WHEN brand RLIKE '^(Stark|Umbrella)$' THEN 'GROUP_A' WHEN brand RLIKE '^(Acme|Globex)$' THEN 'CORE' ELSE 'EXTENDED' END AS brand_zone FROM ranked
